// Generates the thin, agent-specific adapters that point at the canonical files in .harness/.
// Every generated file says so; the source of truth is always .harness/.

import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync, rmSync } from 'node:fs';
import { join, dirname } from 'node:path';

export const AGENTS = ['claude', 'antigravity', 'generic'];
const GENERATED = 'Generated by a-simple-agent-harness. Do not edit: change .harness/ and run `harness sync`.';

function write(path, content) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, content);
}

function yamlString(s) {
  return JSON.stringify(s); // JSON strings are valid YAML double-quoted scalars
}

/** Replace (or append) the content between markers in a text file. */
export function upsertBlock(path, start, end, body) {
  const block = `${start}\n${body.trim()}\n${end}`;
  let text = existsSync(path) ? readFileSync(path, 'utf8') : '';
  const re = new RegExp(`${escapeRe(start)}[\\s\\S]*?${escapeRe(end)}`);
  if (re.test(text)) text = text.replace(re, block);
  else text = text ? `${text.replace(/\s*$/, '')}\n\n${block}\n` : `${block}\n`;
  writeFileSync(path, text);
}

function escapeRe(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function skillBody(cmd, argsPhrase) {
  return `<!-- ${GENERATED} -->

# ${cmd.name}

1. If you have not read it in this session, read \`.harness/HARNESS.md\`.
2. Read \`.harness/${cmd.file}\` and follow it exactly, step by step.
3. Arguments: ${argsPhrase}
${cmd.isolated ? '4. This stage is **isolated**: you must not rely on any earlier conversation. Treat the files as your only input (see `.harness/isolation.md`).\n' : ''}`;
}

function removeStaleSkills(dir, keep) {
  if (!existsSync(dir)) return;
  for (const name of readdirSync(dir)) {
    if (!name.startsWith('harness-') || keep.has(name)) continue;
    const file = join(dir, name, 'SKILL.md');
    if (existsSync(file) && readFileSync(file, 'utf8').includes('Generated by a-simple-agent-harness')) {
      rmSync(join(dir, name), { recursive: true, force: true });
    }
  }
}

// ---------- generic: AGENTS.md (read by Codex, Cursor, Antigravity, Gemini CLI, Claude via import…) ----------
export function generic(target, registry) {
  const rows = registry.commands
    .map((c) => `| \`${c.name}\` | \`.harness/${c.file}\` | ${c.description.replace(/\|/g, '\\|')} |`)
    .join('\n');
  const body = `<!-- ${GENERATED} -->

## Agent harness

This project is built with **a-simple-agent-harness**. Before doing any development work, read
\`.harness/HARNESS.md\`: it defines the pipeline (intake → setup → preflight → plan → bootstrap →
stories → release → report), the two modes (\`supervised\` and \`auto\`), the gates, and the contracts
every agent follows. Configuration lives in \`.harness/config.json\`; what is being built lives in
\`docs/\`.

- To configure a new run: follow \`.harness/stages/01-setup.md\`.
- To start or resume the run: follow \`.harness/orchestrator.md\`.
- If your tool supports skills or slash commands, the same entry points are available as
  \`/harness-setup\` and \`/harness-run\`. Otherwise, ask the agent to "follow \`.harness/<file>\`".

| Command | Canonical file | Purpose |
| ------- | -------------- | ------- |
${rows}

Non-negotiable rules (details in \`.harness/HARNESS.md\` §4):

- Never invent a human approval; in \`supervised\` mode stop at every human gate.
- Never push to the default branch directly when \`git.integration\` is \`pr\`; never force push;
  never \`git add -A\`; never \`--no-verify\`.
- Never write, print or commit secret values.
- Reviews and QA run in an isolated context and are valid only for the commit they checked.`;
  upsertBlock(join(target, 'AGENTS.md'), '<!-- harness:start -->', '<!-- harness:end -->', body);
  return ['AGENTS.md'];
}

// ---------- Claude Code: .claude/skills + CLAUDE.md import + settings deny rules ----------
export function claude(target, registry) {
  const written = [];
  const dir = join(target, '.claude', 'skills');
  removeStaleSkills(dir, new Set(registry.commands.map((c) => c.name)));
  for (const cmd of registry.commands) {
    const fm = [
      '---',
      `name: ${cmd.name}`,
      `description: ${yamlString(cmd.description)}`,
      cmd.args ? `argument-hint: ${yamlString(cmd.args)}` : null,
      cmd.userOnly ? 'disable-model-invocation: true' : null,
      cmd.isolated ? 'context: fork' : null,
      cmd.isolated ? 'agent: general-purpose' : null,
      '---',
      '',
    ]
      .filter((l) => l !== null)
      .join('\n');
    const path = join(dir, cmd.name, 'SKILL.md');
    write(path, fm + skillBody(cmd, '`$ARGUMENTS`'));
    written.push(`.claude/skills/${cmd.name}/SKILL.md`);
  }

  // CLAUDE.md imports AGENTS.md so there is a single set of instructions.
  const claudeMd = join(target, 'CLAUDE.md');
  const current = existsSync(claudeMd) ? readFileSync(claudeMd, 'utf8') : '';
  if (!/^@AGENTS\.md\s*$/m.test(current)) {
    upsertBlock(claudeMd, '<!-- harness:start -->', '<!-- harness:end -->',
      `<!-- ${GENERATED} -->\n\n@AGENTS.md`);
    written.push('CLAUDE.md');
  }

  // Deny rules that protect unattended runs. Merged, never replacing the project's own settings.
  const settingsPath = join(target, '.claude', 'settings.json');
  let settings = {};
  if (existsSync(settingsPath)) {
    try {
      settings = JSON.parse(readFileSync(settingsPath, 'utf8'));
    } catch {
      console.warn('! .claude/settings.json is not valid JSON; deny rules not merged.');
      return written;
    }
  }
  const deny = [
    'Bash(git push --force:*)',
    'Bash(git push -f:*)',
    'Bash(git push --force-with-lease:*)',
    'Bash(git add -A:*)',
    'Bash(git add .:*)',
    'Bash(git commit --no-verify:*)',
    'Bash(gh pr merge --admin:*)',
    'Bash(rm -rf /:*)',
    'Read(./.env)',
    'Read(./.env.*)',
  ];
  settings.permissions ??= {};
  settings.permissions.deny = Array.from(new Set([...(settings.permissions.deny || []), ...deny]));
  write(settingsPath, JSON.stringify(settings, null, 2) + '\n');
  written.push('.claude/settings.json');
  return written;
}

// ---------- Antigravity: .agents/skills + .agents/rules ----------
export function antigravity(target, registry) {
  const written = [];
  const dir = join(target, '.agents', 'skills');
  removeStaleSkills(dir, new Set(registry.commands.map((c) => c.name)));
  for (const cmd of registry.commands) {
    const fm = ['---', `name: ${cmd.name}`, `description: ${yamlString(cmd.description)}`, '---', ''].join('\n');
    const argsPhrase = cmd.args
      ? `whatever the user wrote after the command (expected: \`${cmd.args}\`).`
      : 'none.';
    let body = skillBody(cmd, argsPhrase);
    if (cmd.isolated) {
      body += `\nIf you are the main agent orchestrating the run, start this stage as a **new agent** from the Agent Manager (fresh context) with a self-contained prompt, and wait for its report.\n`;
    }
    write(join(dir, cmd.name, 'SKILL.md'), fm + body);
    written.push(`.agents/skills/${cmd.name}/SKILL.md`);
  }
  write(
    join(target, '.agents', 'rules', 'harness.md'),
    `<!-- ${GENERATED} -->

# Agent harness

This project follows a-simple-agent-harness. Before any development work, read \`AGENTS.md\` and
\`.harness/HARNESS.md\`. Configuration: \`.harness/config.json\`. Entry points: the
\`harness-setup\` and \`harness-run\` skills (or \`.harness/stages/01-setup.md\` and
\`.harness/orchestrator.md\`). Never invent human approvals, never force push, never commit secrets.
`,
  );
  written.push('.agents/rules/harness.md');
  return written;
}

export function generate(target, agents, registry) {
  const fns = { claude, antigravity, generic };
  const out = [];
  for (const a of new Set([...agents, 'generic'])) {
    if (!fns[a]) throw new Error(`Unknown agent "${a}". Known: ${AGENTS.join(', ')}`);
    out.push(...fns[a](target, registry));
  }
  return out;
}
